components.css:
.ds-card-frame { --ds-ink: #1E1914; --ds-paper: #E7D9BD; --ds-red: #901E1E; --ds-chamfer: 9px; width: 168px; min-height: 236px; clip-path: polygon(var(--ds-chamfer) 0, calc(100% - var(--ds-chamfer)) 0, 100% var(--ds-chamfer), 100% calc(100% - var(--ds-chamfer)), calc(100% - var(--ds-chamfer)) 100%, var(--ds-chamfer) 100%, 0 calc(100% - var(--ds-chamfer)), 0 var(--ds-chamfer)); background: var(--ds-ink); padding: 4px; transform: rotate(0.4deg) translate(1px, -1px); }
.ds-card-frame__inner { clip-path: polygon(calc(var(--ds-chamfer) - 3px) 0, calc(100% - var(--ds-chamfer) + 3px) 0, 100% calc(var(--ds-chamfer) - 3px), 100% calc(100% - var(--ds-chamfer) + 3px), calc(100% - var(--ds-chamfer) + 3px) 100%, calc(var(--ds-chamfer) - 3px) 100%, 0 calc(100% - var(--ds-chamfer) + 3px), 0 calc(var(--ds-chamfer) - 3px)); background: var(--ds-paper); height: 100%; min-height: 226px; padding: 22px 16px; box-sizing: border-box; position: relative; }
.ds-card-frame__seal { position: absolute; top: 10px; left: 12px; width: 8px; height: 8px; background: var(--ds-red); }
.ds-card-frame__title { margin-top: 34px; font-family: "IM Fell English SC", Georgia, serif; font-size: 34px; font-weight: 400; color: var(--ds-ink); text-align: center; }
.ds-card-frame__role { font-family: "Alegreya Sans", Verdana, sans-serif; font-size: 19px; font-weight: 500; color: #544636; text-align: center; border-top: 2px solid var(--ds-ink); padding-top: 6px; }
.ds-card-frame:focus-visible { outline: 3px solid var(--ds-red); outline-offset: 4px; }
.ds-card-frame.is-dashed { background: repeating-linear-gradient(90deg, var(--ds-ink) 0 10px, transparent 10px 17px), repeating-linear-gradient(0deg, var(--ds-ink) 0 10px, transparent 10px 17px); background-clip: content-box; }

.ds-chip { font-family: "Alegreya Sans", Verdana, sans-serif; font-size: 22px; color: #1E1914; background: #D5C5A5; border: 2px solid #1E1914; border-radius: 4px; padding: 9px 14px; min-height: 48px; cursor: pointer; display: block; margin-bottom: 6px; text-align: left; }
.ds-chip:hover { background: #E7D9BD; }
.ds-chip:active { background: #C4B598; border-color: #901E1E; }
.ds-chip:focus-visible { outline: 3px solid #901E1E; outline-offset: 3px; }
.ds-chip:disabled { background: #CBBB9D; border-color: #544636; color: #544636; text-decoration: line-through; text-decoration-thickness: 3px; }

.ds-chronicle { display: flex; align-items: center; gap: 10px; min-height: 48px; background: #3C342B; color: #E7D9BD; font-family: "Alegreya Sans", Verdana, sans-serif; font-style: italic; font-size: 22px; padding: 0 8px; white-space: nowrap; overflow: hidden; }
.ds-chronicle__rule { flex: 0 0 30px; height: 3px; background: #E7D9BD; position: relative; }
.ds-chronicle.is-warn .ds-chronicle__rule { background: repeating-linear-gradient(90deg, #E7D9BD 0 6px, transparent 6px 9px); }
.ds-chronicle.is-strike .ds-chronicle__rule { background: rgba(231,217,189,0.6); }
.ds-chronicle.is-strike .ds-chronicle__rule::after { content: ""; position: absolute; left: 8px; top: -4px; width: 14px; height: 3px; background: #E7D9BD; transform: rotate(-45deg); }
.ds-chronicle.is-victory .ds-chronicle__rule { background: none; border-top: 2px solid rgba(231,217,189,0.7); border-bottom: 2px solid rgba(231,217,189,0.7); height: 6px; }

.ds-pip-row { display: flex; gap: 18px; background: #3C342B; padding: 6px; }
.ds-pip { display: flex; align-items: center; gap: 8px; min-width: 72px; min-height: 48px; }
.ds-pip__glyph { width: 38px; height: 38px; display: inline-flex; align-items: center; justify-content: center; background: #E7D9BD; border: 3px solid #1E1914; box-sizing: border-box; }
.ds-pip__glyph--food { border-radius: 50%; }
.ds-pip__glyph--timber { border-radius: 0; }
.ds-pip__glyph--iron { border-radius: 0; clip-path: polygon(25% 0, 75% 0, 100% 50%, 75% 100%, 25% 100%, 0 50%); border: none; outline: 3px solid #1E1914; outline-offset: -6px; }
.ds-pip__col { display: flex; flex-direction: column; }
.ds-pip__amount { font-family: "Alegreya Sans", Verdana, sans-serif; font-size: 26px; font-weight: 700; color: #1E1914; line-height: 1.1; }
.ds-pip__label { font-family: "Alegreya Sans", Verdana, sans-serif; font-size: 15px; font-weight: 500; color: #544636; letter-spacing: 0.04em; }

.ds-panel { background: #E7D9BD; border: 3px solid #1E1914; border-radius: 5px; padding: 14px; max-width: 560px; font-family: "Alegreya Sans", Verdana, sans-serif; color: #1E1914; }
.ds-panel__title { font-family: "IM Fell English SC", Georgia, serif; font-size: 34px; margin-bottom: 8px; }
.ds-panel__row { font-size: 22px; font-style: italic; border-top: 3px solid #1E1914; padding: 6px 0; }

.ds-run-header { display: flex; align-items: center; gap: 14px; background: #3B2E1F; padding: 6px 12px; min-height: 48px; }
.ds-run-header__name { font-family: "IM Fell English SC", Georgia, serif; font-size: 28px; color: #E7D9BD; flex: 1; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.ds-run-header__rule { width: 30px; height: 3px; background: #CCA34C; }
.ds-run-header__regime { font-family: "Alegreya Sans", Verdana, sans-serif; font-size: 19px; font-weight: 500; color: #CCA34C; letter-spacing: 0.05em; }
.ds-run-header__clock { font-family: "Alegreya Sans", Verdana, sans-serif; font-size: 15px; font-weight: 500; color: #E7D9BD; }
